DROP TABLE IF EXISTS `hotel_audit_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `hotel_audit_records` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hotelId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '酒店ID',
  `action` enum('SUBMIT','APPROVE','REJECT','PUBLISH','OFFLINE','RESTORE','WITHDRAW','OFFLINE_REQUEST') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作类型',
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  `operatorId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人ID',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `IDX_25759cb97c5508f3fb2039bcdf` (`hotelId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

