--
-- Table structure for table `room_types`
--

DROP TABLE IF EXISTS `room_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `room_types` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hotelId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房型名称',
  `basePrice` decimal(10,2) NOT NULL COMMENT '房型基础价格',
  `maxGuests` int(11) DEFAULT NULL COMMENT '可住人数',
  `bedType` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '床型',
  `sortOrder` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  `stock` int(11) DEFAULT NULL COMMENT '库存',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '房型图片',
  `isOnSale` tinyint(4) DEFAULT NULL COMMENT '是否开售',
  `hasBreakfast` tinyint(4) DEFAULT NULL COMMENT '含早',
  `refundable` tinyint(4) DEFAULT NULL COMMENT '可退',
  `area` decimal(6,2) DEFAULT NULL COMMENT '房间面积(㎡)',
  `floor` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '楼层',
  `hasWindow` tinyint(4) DEFAULT NULL COMMENT '有窗',
  PRIMARY KEY (`id`),
  KEY `IDX_7ed42fc166559badb3c937c400` (`hotelId`),
  CONSTRAINT `FK_7ed42fc166559badb3c937c400c` FOREIGN KEY (`hotelId`) REFERENCES `hotels` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

